<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText} from '$lib/shared/presentation/copy';
 import Icon from '$lib/shared/presentation/ui/Icon.svelte';
 import {onMount,untrack} from 'svelte';
 import {NotificationFeed} from '../application/feed';
 import type {Notification,NotificationsGateway} from '../application/notifications';
 let {gateway}:{gateway:NotificationsGateway}=$props();
 const {locale}=useLocale();let version=$state(0);
 const feed=new NotificationFeed(untrack(()=>gateway),()=>version++);
 const unreadOnly=$derived.by(()=>{version;return feed.unreadOnly;});
 const kind=$derived.by(()=>{version;return feed.kind;});
 const account=$derived.by(()=>{version;return feed.account;}),items=$derived.by(()=>{version;return feed.items;}),busy=$derived.by(()=>{version;return feed.busy;}),more=$derived.by(()=>{version;return feed.more;}),message=$derived.by(()=>{version;return feed.error;});
 const dayKey=(value:string)=>new Date(value).toLocaleDateString('en-CA');
 const days=$derived.by(()=>{const groups=new Map<string,Notification[]>();for(const item of items){const key=dayKey(item.createdAt);groups.set(key,[...(groups.get(key)||[]),item]);}return [...groups.entries()];});
 function dayName(value:string){const now=new Date();if(value===dayKey(now.toISOString()))return text($locale,'Бүгін','Сегодня');now.setDate(now.getDate()-1);if(value===dayKey(now.toISOString()))return text($locale,'Кеше','Вчера');return new Date(value+'T12:00:00').toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ',{day:'numeric',month:'long',year:'numeric'});}
 function label(item:Notification){return item.kind==='new_release'?text($locale,'Жаңа тарау','Новая глава'):item.kind==='comment_reply'?text($locale,'Пікірге жауап','Ответ на комментарий'):item.kind==='profile_followed'?text($locale,'Жаңа жазылушы','Новый подписчик'):item.kind==='publication_published'?text($locale,'Тарау жарияланды','Глава опубликована'):item.kind==='publication_rejected'?text($locale,'Тарау түзетуге қайтарылды','Глава возвращена на исправление'):item.kind==='publication_withdrawn'?text($locale,'Тарау оқудан алынды','Глава снята с публикации'):item.kind==='project_request_approved'?text($locale,'Жоба өтінімі мақұлданды','Заявка на проект одобрена'):item.kind==='project_request_rejected'?text($locale,'Жоба өтінімі қайтарылды','Заявка на проект возвращена'):copy($locale,'Хабарлар');}
 function destination(item:Notification){if(item.kind==='comment_reply'&&item.commentId&&(item.releaseId||item.titleSlug))return item.releaseId?`/read/${encodeURIComponent(item.releaseId)}?comment=${encodeURIComponent(item.commentId)}`:`/titles/${encodeURIComponent(item.titleSlug)}?tab=comments&comment=${encodeURIComponent(item.commentId)}`;if(item.projectId)return '/studio/projects/'+encodeURIComponent(item.projectId);if(item.kind.startsWith('project_request_'))return '/studio/requests';if(item.releaseId)return '/read/'+encodeURIComponent(item.releaseId);if(item.titleSlug)return '/titles/'+encodeURIComponent(item.titleSlug);if(item.kind==='profile_followed'&&account)return '/users/'+encodeURIComponent(account);return '';}
 onMount(()=>{const stop=gateway.watchAccountChange?.(()=>{feed.reset();void feed.load();});void feed.load();return()=>{stop?.();feed.close();};});
</script>
<svelte:head><title>{copy($locale,'Хабарлар — Qmanga')}</title><meta name="robots" content="noindex"/></svelte:head>
<div class="notifications-page"><header class="notifications-heading"><div><p class="eyebrow">{text($locale,'Сізді не күтеді','Для тебя')}</p><h1>{copy($locale,'Хабарлар')}</h1><p class="muted">{text($locale,'Жаңа тараулар мен жауаптар уақытымен.','Новые главы и ответы — всё вовремя.')}</p></div>{#if account&&gateway.readAll}<button class="mark-all" disabled={busy||!items.some(item=>!item.read)} onclick={()=>feed.readAll()}><Icon name="check" size={16}/>{text($locale,'Бәрін оқылды деп белгілеу','Отметить всё прочитанным')}</button>{/if}</header>
<nav class="notification-filter" aria-label={text($locale,'Хабарларды сүзу','Фильтр уведомлений')}><button aria-pressed={!unreadOnly&&!kind} onclick={()=>feed.setFilter(false,'')}>{text($locale,'Барлығы','Все')}</button><button aria-pressed={unreadOnly&&!kind} onclick={()=>feed.setFilter(true,'')}>{text($locale,'Оқылмаған','Непрочитанные')}</button><button aria-pressed={kind==='chapters'} onclick={()=>feed.setFilter(false,'chapters')}>{text($locale,'Тараулар','Главы')}</button><button aria-pressed={kind==='replies'} onclick={()=>feed.setFilter(false,'replies')}>{text($locale,'Жауаптар','Ответы')}</button></nav>
{#if message}<p class="form-message" role="status">{noticeText($locale,message)}</p><button class="button" disabled={busy} onclick={()=>feed.load(feed.cursor)}>{text($locale,'Қайталау','Повторить')}</button>{/if}
{#if !account&&!busy&&!message}<p>{copy($locale,'Хабарларды көру үшін ')}<a class="auth-link" href="/login?returnTo=%2Fnotifications">{copy($locale,'кіріңіз')}</a>.</p>{/if}
<div class="notification-timeline">{#each days as [day,entries]}<section class="notification-day" aria-label={dayName(day)}><h2>{dayName(day)}</h2>{#each entries as item (item.id)}<article class:unread={!item.read}><div class="notification-icon"><Icon name={item.kind==='new_release'?'bookmark':item.kind==='comment_reply'?'message':item.kind==='profile_followed'?'user':'shield'} size={18}/></div><div class="notification-content"><div class="notification-meta"><span>{label(item)}</span><time datetime={item.createdAt}>{new Date(item.createdAt).toLocaleTimeString($locale==='ru'?'ru-RU':'kk-KZ',{hour:'2-digit',minute:'2-digit'})}</time></div><h3>{item.body||label(item)}</h3>{#if !item.read}<span class="unread-label">{text($locale,'Оқылмаған','Не прочитано')}</span>{/if}<div class="notification-actions">{#if destination(item)}<a href={destination(item)} onclick={()=>feed.read(item)}>{item.kind==='new_release'?text($locale,'Тарауды ашу','Открыть главу'):text($locale,'Қарау','Посмотреть')}<Icon name="right" size={14}/></a>{/if}{#if !item.read}<button type="button" disabled={busy} onclick={()=>feed.read(item)} aria-label={copy($locale,'Оқылды деп белгілеу')} title={copy($locale,'Оқылды деп белгілеу')}><Icon name="check" size={16}/></button>{/if}</div></div></article>{/each}</section>{:else}{#if account&&!busy&&!message}<p class="empty-state">{unreadOnly?text($locale,'Оқылмаған хабар жоқ.','Непрочитанных уведомлений нет.'):text($locale,'Әзірге хабар жоқ.','Уведомлений пока нет.')}</p>{/if}{/each}</div>
{#if more}<button class="button subtle" disabled={busy} onclick={()=>feed.load(feed.cursor)}>{copy($locale,'Тағы жүктеу')}</button>{/if}{#if busy}<p role="status">{copy($locale,'Жүктелуде…')}</p>{/if}
<footer class="notification-settings"><p class="eyebrow">{text($locale,'Хабарларды басқару','Управление уведомлениями')}</p><h2>{text($locale,'Тек керекті жаңалықтар.','Только нужные новости.')}</h2><p class="muted">{text($locale,'Тараулар, жауаптар мен пошта хабарларын бөлек баптаңыз.','Настрой главы, ответы и письма по отдельности.')}</p><a href="/settings?section=notifications">{text($locale,'Хабар баптаулары','Настройки уведомлений')}<Icon name="right" size={16}/></a></footer></div>
<style>
 .notifications-page{max-width:760px}.notifications-heading{display:flex;align-items:start;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:8px 0 20px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:1.2px;font-weight:650;color:var(--accent);margin:0 0 8px}h1{font-size:28px;margin:0 0 8px;letter-spacing:-.6px}.muted{font-size:13px;line-height:1.7;margin:0}.mark-all{display:flex;align-items:center;gap:8px;min-height:44px;padding:8px 12px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--text);font-size:12px}.notification-filter{display:flex;overflow:auto;border-bottom:1px solid var(--line);margin-bottom:24px;scrollbar-width:none}.notification-filter button{min-height:48px;flex:1;padding:8px 10px;border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);font-size:12px;white-space:nowrap}.notification-filter [aria-pressed=true]{border-bottom-color:var(--accent);color:var(--text)}.notification-day{border-left:1px solid var(--line);padding:0 0 12px 14px;margin-bottom:20px}.notification-day>h2{font-size:12px;margin:0 0 16px 0;line-height:20px}.notification-day article{position:relative;display:flex;gap:12px;padding:16px 14px;border:1px solid var(--line);border-radius:7px;background:var(--panel);margin-bottom:12px;min-width:0}.notification-day article::before{content:'';position:absolute;width:5px;height:5px;border-radius:50%;left:-18px;top:20px;background:var(--muted)}.notification-day article.unread{border-left-color:var(--accent)}.notification-day article.unread::before{background:var(--accent)}.notification-icon{display:grid;place-items:center;width:28px;height:28px;flex:none;background:var(--raised);border-radius:50%;color:var(--muted)}.unread .notification-icon{color:var(--accent)}.notification-content{min-width:0;flex:1}.notification-meta{display:flex;justify-content:space-between;gap:12px;font-size:10px;line-height:1.5;color:var(--muted)}.notification-meta>span{text-transform:uppercase;letter-spacing:.5px}time{flex:none}h3{font-size:14px;line-height:1.6;margin:8px 0;overflow-wrap:anywhere;white-space:pre-wrap}.unread-label{font-size:11px;color:var(--muted)}.notification-actions{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:10px}.notification-actions a{display:flex;align-items:center;gap:6px;min-height:44px;font-size:12px;color:var(--accent);text-decoration:none}.notification-actions button{display:grid;place-items:center;width:44px;min-height:44px;border:0;background:none;color:var(--muted);border-radius:6px}.notification-settings{border-top:1px solid var(--line);padding-top:28px;margin-top:36px}.notification-settings h2{font-size:23px;margin:8px 0 12px;letter-spacing:-.4px}.notification-settings>a{display:inline-flex;align-items:center;gap:8px;min-height:44px;font-size:12px;color:var(--accent);margin-top:16px}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}@media(max-width:359px){.notification-filter button{padding-inline:6px;font-size:11px}.notification-day article{padding:12px 10px;gap:8px}.notification-icon{width:24px;height:24px}}
</style>
